// Demo: Hybrid Search Engine - Signature build-tool concept
(function(){'use strict';
var DATA={"label": "Hybrid Search Engine - Signature build-tool concept", "arr": [14, 32, 83, 96, 114, 121, 126, 136, 141, 183], "target": 32};

var a=DATA.arr,t=DATA.target,lo=0,hi=a.length-1,steps=0;
console.log('Binary search for '+t+' in ['+a.join(', ')+'] ('+DATA.label+'):');
while(lo<=hi){var mid=(lo+hi)>>1;steps++;
  console.log('  step '+steps+': mid='+mid+' value='+a[mid]);
  if(a[mid]===t){console.log('FOUND at index '+mid+' in '+steps+' steps');break;}
  else if(a[mid]<t)lo=mid+1;else hi=mid-1;}
if(lo>hi)console.log('NOT FOUND after '+steps+' steps');
})();

// JAH demo program - run with: node demo.js (or paste into a browser console)
// Demo: Signature Indexer - Hybrid Search Engine framework pillar
(function(){'use strict';
var DATA={"label": "Signature Indexer - Hybrid Search Engine framework pillar", "docs": [{"id": "AIB-HSE2-000001", "text": "Hybrid Search Engine - Signature build-tool concept. Combines keyword matching with semantic similarity."}], "query": "indexer"};

var idx={};
DATA.docs.forEach(function(d){
  d.text.toLowerCase().split(/[^a-z0-9]+/).forEach(function(t){
    if(!t)return;(idx[t]=idx[t]||{})[d.id]=(idx[t][d.id]||0)+1;});});
var q=DATA.query.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean),scores={};
q.forEach(function(t){var post=idx[t]||{};
  Object.keys(post).forEach(function(id){scores[id]=(scores[id]||0)+post[id];});});
var ranked=Object.keys(scores).sort(function(a,b){return scores[b]-scores[a];});
console.log('Query "'+DATA.query+'" ('+DATA.label+'):');
if(!ranked.length)console.log('  no matches');
ranked.forEach(function(id,i){var d=DATA.docs.filter(function(x){return x.id===id;})[0];
  console.log('  '+(i+1)+'. '+d.id+' score='+scores[id]+' :: '+d.text.slice(0,60));});
})();

